sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var AUDIT = 'x_gegis_ins_policy_extraction_field_audit';
    var COL = 'manual_value';
    var MAX = 100;                       // audit old_value / new_value width

    // INSERT is not a revision. A row arriving with a manual_value already set
    // is a data load, and its history (if any) arrives with it - writing a row
    // here would duplicate the version 1 that came from the file. The audit
    // records what a human changes AFTER the field exists.
    if (current.isNewRecord())
        return;

    var newValue = String(current.getValue(COL) || '');
    var oldValue = String(previous.getValue(COL) || '');

    // only a real change to manual_value is a revision - editing review_status,
    // confidence or anything else must not burn a version number
    if (newValue === oldValue)
        return;

    // version counts MANUAL revisions, so the first manual value is 1 - not 2.
    // The field's own version column defaults to 1 before anything is typed, so
    // reading previous.version and adding one would start the audit at 2 and no
    // row would ever carry version 1.
    var version = oldValue
        ? (parseInt(previous.getValue('version'), 10) || 1) + 1
        : 1;

    // stamped in this same write - no second update(), so no recursion
    current.setValue('version', version);

    var audit = new GlideRecord(AUDIT);
    if (!audit.isValid()) {
        gs.error('[extraction_field] ' + AUDIT + ' is missing - ' + COL
            + ' change on ' + current.getUniqueValue() + ' was NOT audited');
        return;
    }

    audit.initialize();
    audit.setValue('version', version);
    audit.setValue('extraction_field', current.getUniqueValue());
    audit.setValue('changed_field', COL);
    audit.setValue('old_value', oldValue.substring(0, MAX));
    audit.setValue('new_value', newValue.substring(0, MAX));
    // the NAME, not the sys_id: changed_by is a plain string, and an audit row
    // has to stay readable after the user is renamed or deactivated
    audit.setValue('changed_by', gs.getUserDisplayName());
    audit.setValue('changed_on', new GlideDateTime());

    // insert() returns null when an ACL, a data policy or a mandatory column
    // blocks the write. Unchecked, the field change would still go through and
    // the revision would be lost in silence - the one failure an audit trail
    // cannot be allowed to have.
    if (!audit.insert()) {
        gs.error('[extraction_field] audit row REFUSED for ' + current.getUniqueValue()
            + ' v' + version + ' ("' + oldValue + '" -> "' + newValue
            + '") - check ACLs on ' + AUDIT);
    }

})(current, previous);
